#!/usr/bin/env python3
"""Builds todo_implement2.js: the table of the points (notes for each agent) + the workflow of todo_implement.js.

The table is the orchestrator's knowledge of TODO.md: which points make a chain (the second one is made on the
branch of the first because it changes the same code), what each agent should look at, how to validate."""
import json, re, sys

SCR = "/tmp/claude-1001/-home-jninin-Documents-WORK-DEV-GAOL-GAOL-V8/334ea319-d088-4702-9b10-e0628647c222/scratchpad"

P = {}


def point(id, slug, title, risk, notes, chain_note=None, validate=None, lenses=None, todo=None):
    P[id] = dict(id=id, slug=slug, branch="todo-" + slug, title=title, risk=risk, notes=notes.strip())
    if todo is not None:
        P[id]["todo"] = todo
    if chain_note:
        P[id]["chainNote"] = chain_note.strip()
    if validate:
        P[id]["validate"] = validate.strip()
    if lenses:
        P[id]["lenses"] = lenses


